style.css:
@-moz-document domain("youtube.com") {
/* ==========================================================================
       1. GLOBAL RESET & APPLE SF TYPOGRAPHY
       ========================================================================== */
    * {
        font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "SF Pro Icons", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
        -webkit-font-smoothing: antialiased !important;
        -moz-osx-font-smoothing: grayscale !important;
    }

    /* ==========================================================================
       2. DYNAMIC LIQUID BACKGROUND & THEME OVERRIDES
       ========================================================================== */
    html, body, ytd-app {
        background: #08090e !important;
        background-image: 
            radial-gradient(circle at 10% 20%, rgba(99, 102, 241, 0.18) 0%, transparent 45%),
            radial-gradient(circle at 90% 80%, rgba(236, 72, 153, 0.16) 0%, transparent 45%),
            radial-gradient(circle at 50% 50%, rgba(16, 185, 129, 0.1) 0%, transparent 55%),
            linear-gradient(135deg, #06070a 0%, #0c0e17 50%, #050609 100%) !important;
        background-attachment: fixed !important;
        background-size: cover !important;
    }

    html[dark], [dark], ytd-app {
        --yt-spec-base-background: transparent !important;
        --yt-spec-general-background-a: transparent !important;
        --yt-spec-general-background-b: transparent !important;
        --yt-spec-general-background-c: transparent !important;
        --yt-spec-menu-background: rgba(20, 22, 32, 0.75) !important;
        --yt-spec-raised-background: transparent !important;
        --yt-spec-touch-response: rgba(255, 255, 255, 0.1) !important;
    }

    /* ==========================================================================
       3. FLOATING GLASS HEADER (iOS DOCK TOP BAR)
       ========================================================================== */
    #masthead-container {
        background: transparent !important;
        padding: 12px 20px 0 20px !important;
        position: fixed !important;
        top: 0 !important;
        width: 100% !important;
        z-index: 2000 !important;
        box-sizing: border-box !important;
    }

    ytd-masthead {
        background: rgba(18, 20, 30, 0.55) !important;
        backdrop-filter: blur(40px) saturate(220%) contrast(105%) !important;
        -webkit-backdrop-filter: blur(40px) saturate(220%) contrast(105%) !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
        border-radius: 28px !important;
        box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45), inset 0 1px 1px rgba(255, 255, 255, 0.25) !important;
        margin: 0 auto !important;
        height: 60px !important;
        padding: 0 16px !important;
        transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;
    }

    /* ==========================================================================
       4. SEARCH BAR - iOS 27 PILL SHAPE WITH GLOW
       ========================================================================== */
    #container.ytd-searchbox, 
    ytd-searchbox[has-focus] #container.ytd-searchbox {
        background: rgba(255, 255, 255, 0.08) !important;
        border: 1px solid rgba(255, 255, 255, 0.18) !important;
        border-radius: 9999px !important;
        backdrop-filter: blur(20px) !important;
        box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.2), 0 4px 20px rgba(0, 0, 0, 0.15) !important;
        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
        padding-left: 18px !important;
    }

    #container.ytd-searchbox:focus-within {
        background: rgba(255, 255, 255, 0.16) !important;
        border-color: rgba(255, 255, 255, 0.4) !important;
        box-shadow: 0 0 25px rgba(255, 255, 255, 0.2), inset 0 1px 2px rgba(255, 255, 255, 0.3) !important;
    }

    #search-icon-legacy.ytd-searchbox {
        display: none !important;
    }

    /* Voice Search Button */
    #voice-search-button.ytd-masthead {
        background: rgba(255, 255, 255, 0.1) !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
        border-radius: 50% !important;
        backdrop-filter: blur(15px) !important;
        transition: all 0.25s ease !important;
    }
    #voice-search-button.ytd-masthead:hover {
        background: rgba(255, 255, 255, 0.22) !important;
        transform: scale(1.08);
    }

    /* ==========================================================================
       5. SIDEBAR / NAVIGATION (FLOATING GLASS DOCK)
       ========================================================================== */
    ytd-guide-renderer, #guide-content, app-drawer {
        background: rgba(14, 16, 25, 0.5) !important;
        backdrop-filter: blur(40px) saturate(200%) !important;
        -webkit-backdrop-filter: blur(40px) saturate(200%) !important;
        border-right: 1px solid rgba(255, 255, 255, 0.12) !important;
        border-top-right-radius: 32px !important;
        border-bottom-right-radius: 32px !important;
        box-shadow: 10px 0 35px rgba(0, 0, 0, 0.3) !important;
    }

    ytd-guide-entry-renderer, ytd-mini-guide-entry-renderer {
        border-radius: 18px !important;
        margin: 4px 12px !important;
        transition: all 0.28s cubic-bezier(0.16, 1, 0.3, 1) !important;
    }

    ytd-guide-entry-renderer:hover, ytd-mini-guide-entry-renderer:hover {
        background: rgba(255, 255, 255, 0.14) !important;
        transform: translateX(5px) scale(1.02);
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25) !important;
    }

    ytd-guide-entry-renderer[focused], ytd-guide-entry-renderer[active] {
        background: rgba(255, 255, 255, 0.22) !important;
        border: 1px solid rgba(255, 255, 255, 0.25) !important;
    }

    /* ==========================================================================
       6. VIDEO CARDS & SHORTS (iOS WIDGET FLOATING TILES)
       ========================================================================== */
    ytd-rich-item-renderer, 
    ytd-video-renderer, 
    ytd-grid-video-renderer, 
    ytd-compact-video-renderer {
        background: rgba(20, 23, 35, 0.48) !important;
        border: 1px solid rgba(255, 255, 255, 0.12) !important;
        border-radius: 26px !important;
        padding: 14px !important;
        backdrop-filter: blur(30px) saturate(180%) !important;
        -webkit-backdrop-filter: blur(30px) saturate(180%) !important;
        box-shadow: 0 12px 35px rgba(0, 0, 0, 0.3), inset 0 1px 1px rgba(255, 255, 255, 0.18) !important;
        transition: all 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important;
        margin-bottom: 18px !important;
    }

    ytd-rich-item-renderer:hover, 
    ytd-video-renderer:hover, 
    ytd-compact-video-renderer:hover {
        transform: translateY(-8px) scale(1.018) !important;
        background: rgba(30, 35, 52, 0.65) !important;
        border-color: rgba(255, 255, 255, 0.3) !important;
        box-shadow: 0 22px 50px rgba(0, 0, 0, 0.45), 0 0 30px rgba(255, 255, 255, 0.1) !important;
    }

    /* Thumbnail Styling */
    ytd-thumbnail {
        border-radius: 18px !important;
        overflow: hidden !important;
        box-shadow: 0 8px 25px rgba(0, 0, 0, 0.35) !important;
    }

    ytd-thumbnail-overlay-time-status-renderer {
        background: rgba(10, 12, 18, 0.8) !important;
        backdrop-filter: blur(12px) !important;
        border-radius: 10px !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        padding: 3px 8px !important;
        font-weight: 600 !important;
        letter-spacing: 0.3px !important;
    }

    /* Shorts Container Widget */
    ytd-rich-section-renderer {
        background: rgba(15, 17, 26, 0.4) !important;
        border-radius: 32px !important;
        padding: 20px !important;
        backdrop-filter: blur(30px) !important;
        border: 1px solid rgba(255, 255, 255, 0.12) !important;
        box-shadow: 0 15px 40px rgba(0, 0, 0, 0.3) !important;
        margin-bottom: 24px !important;
    }

    /* ==========================================================================
       7. FILTER CHIPS (iOS PILL BUTTONS)
       ========================================================================== */
    yt-chip-cloud-chip-renderer {
        background: rgba(255, 255, 255, 0.08) !important;
        border-radius: 9999px !important;
        border: 1px solid rgba(255, 255, 255, 0.14) !important;
        backdrop-filter: blur(20px) !important;
        color: #ffffff !important;
        font-weight: 500 !important;
        padding: 0 18px !important;
        transition: all 0.28s cubic-bezier(0.16, 1, 0.3, 1) !important;
    }

    yt-chip-cloud-chip-renderer[selected] {
        background: rgba(255, 255, 255, 0.3) !important;
        border-color: rgba(255, 255, 255, 0.45) !important;
        box-shadow: 0 0 25px rgba(255, 255, 255, 0.25) !important;
    }

    yt-chip-cloud-chip-renderer:hover {
        background: rgba(255, 255, 255, 0.2) !important;
        transform: translateY(-2px) scale(1.03);
    }

    /* ==========================================================================
       8. HIGH CONTRAST TYPOGRAPHY & SHADOWS
       ========================================================================== */
    #video-title, 
    #video-title-link, 
    .yt-core-attributed-string {
        color: #ffffff !important;
        font-weight: 600 !important;
        letter-spacing: -0.01em !important;
        text-shadow: 0 2px 8px rgba(0, 0, 0, 0.7) !important;
    }

    #channel-name #text, 
    #metadata-line span {
        color: rgba(255, 255, 255, 0.75) !important;
        font-weight: 400 !important;
    }

    /* ==========================================================================
       9. POPUPS, DROPDOWN MENUS & MODALS
       ========================================================================== */
    tp-yt-paper-dialog, 
    ytd-multi-page-menu-renderer, 
    tp-yt-iron-dropdown, 
    #contentWrapper.tp-yt-iron-dropdown {
        background: rgba(18, 20, 32, 0.72) !important;
        backdrop-filter: blur(45px) saturate(220%) !important;
        -webkit-backdrop-filter: blur(45px) saturate(220%) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        border-radius: 28px !important;
        box-shadow: 0 30px 70px rgba(0, 0, 0, 0.55), inset 0 1px 1px rgba(255, 255, 255, 0.25) !important;
    }

    ytd-menu-service-item-renderer:hover {
        background: rgba(255, 255, 255, 0.15) !important;
        border-radius: 14px !important;
    }

    /* ==========================================================================
       10. WATCH PAGE & COMMENTS GLASSMORPHISM
       ========================================================================== */
    #watch7-content, ytd-watch-flexy {
        background: transparent !important;
    }

    ytd-comments {
        background: rgba(18, 20, 30, 0.45) !important;
        backdrop-filter: blur(30px) !important;
        border: 1px solid rgba(255, 255, 255, 0.12) !important;
        border-radius: 28px !important;
        padding: 24px !important;
        box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25) !important;
        margin-top: 24px !important;
    }

    /* ==========================================================================
       11. CUSTOM iOS FLOATING SCROLLBAR
       ========================================================================== */
    ::-webkit-scrollbar {
        width: 8px !important;
        height: 8px !important;
    }
    ::-webkit-scrollbar-track {
        background: transparent !important;
    }
    ::-webkit-scrollbar-thumb {
        background: rgba(255, 255, 255, 0.22) !important;
        border-radius: 9999px !important;
        backdrop-filter: blur(12px) !important;
        border: 2px solid transparent !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: rgba(255, 255, 255, 0.45) !important;
    }
}
